export function buildPenaltyRows() {
  const rows = [
    ['Расчет неустойки', '', '', '', '', '', '', '', '', '', '', '', ''],
    ['', '', '', '', '', '', '', '', '', '', '', '', ''],
    [
      'начисленная плата за жилое помещение',
      '',
      'задолженность, руб.',
      'произведенная оплата',
      '',
      'просрочка оплаты/возврата',
      '',
      '',
      'ключевая ставка ЦБ РФ, %',
      'сумма неустойки, руб.',
      '',
      '',
      '',
    ],
    ['дата начисления', 'сумма, руб.', '', 'дата', 'сумма, руб.', 'с', 'по', 'в днях', '', '', '', '', ''],
  ];

  const dataStartRow = rows.length;
  MOCK_DATA_ROWS.forEach((row) => rows.push(row));
  const dataEndRow = rows.length - 1;

  const totalRow = rows.length;
  rows.push(['Итого:', '', '1,100.00', '', '', '', '', '', '', '47.37', '', '', '']);

  const merges = [
    { s: { c: 0, r: 0 }, e: { c: LAST_COL, r: 0 } },
    { s: { c: 0, r: 2 }, e: { c: 1, r: 2 } },
    { s: { c: 2, r: 2 }, e: { c: 2, r: 3 } },
    { s: { c: 3, r: 2 }, e: { c: 4, r: 2 } },
    { s: { c: 5, r: 2 }, e: { c: 7, r: 2 } },
    { s: { c: 8, r: 2 }, e: { c: 8, r: 3 } },
    { s: { c: 9, r: 2 }, e: { c: 9, r: 3 } },
  ];

  const cols = [
    { wch: 16 }, // дата начисления
    { wch: 12 }, // сумма начисления
    { wch: 14 }, // задолженность
    { wch: 12 }, // дата оплаты
    { wch: 12 }, // сумма оплаты
    { wch: 12 }, // просрочка с
    { wch: 12 }, // просрочка по
    { wch: 9 }, // в днях
    { wch: 16 }, // ключевая ставка
    { wch: 16 }, // сумма неустойки
    { wch: 10 },
    { wch: 10 },
    { wch: 10 },
  ];

  return {
    rows,
    merges,
    cols,
    headerStartRow: 2,
    headerEndRow: 3,
    dataStartRow,
    dataEndRow,
    totalRow,
    lastCol: LAST_COL,
  };
}

function border(style = 'thin') {
  const side = { style, color: { rgb: '000000' } };
  return { top: side, bottom: side, left: side, right: side };
}

const HEADER_STYLE = {
  font: { bold: true },
  alignment: { horizontal: 'center', vertical: 'center', wrapText: true },
  border: border(),
};

const DATA_STYLE = {
  alignment: { horizontal: 'center', vertical: 'center' },
  border: border(),
};

const TOTAL_LABEL_STYLE = {
  font: { bold: true },
  alignment: { horizontal: 'left', vertical: 'center' },
};

const TOTAL_DATA_STYLE = {
  alignment: { horizontal: 'center', vertical: 'center' },
};

const TITLE_STYLE = {
  font: { bold: true, sz: 14 },
  alignment: { horizontal: 'center', vertical: 'center' },
};

export function applyPenaltyStyles(XLSX, worksheet, meta) {
  const { headerStartRow, totalRow, lastCol } = meta;

  const setStyle = (r, c, style) => {
    const addr = XLSX.utils.encode_cell({ r, c });
    if (!worksheet[addr]) worksheet[addr] = { t: 's', v: '' };
    worksheet[addr].s = style;
  };

  setStyle(0, 0, TITLE_STYLE);

  for (let r = headerStartRow; r <= totalRow; r += 1) {
    for (let c = 0; c <= lastCol; c += 1) {
      const isHeaderRow = r === headerStartRow || r === headerStartRow + 1;
      const isTotalRow = r === totalRow;
      if (isHeaderRow) {
        setStyle(r, c, HEADER_STYLE);
      } else if (isTotalRow && c === 0) {
        setStyle(r, c, TOTAL_LABEL_STYLE);
      } else if (isTotalRow) {
        setStyle(r, c, TOTAL_DATA_STYLE);
      } else {
        setStyle(r, c, DATA_STYLE);
      }
    }
  }
}
